using System.Security.Cryptography;
using System.Text;

namespace OAuthLab;

// The plumbing of the authorization server: registered clients, token minting and introspection.
// You do not edit this file. The behavior the lab is about lives in AuthorizationServer.cs.
public sealed partial class AuthorizationServer
{
    public const string Issuer = "https://as.lab.test";
    public static readonly TimeSpan CodeLifetime = TimeSpan.FromSeconds(60);
    public static readonly TimeSpan AccessTokenLifetime = TimeSpan.FromSeconds(300);
    public static readonly TimeSpan RefreshTokenLifetime = TimeSpan.FromMinutes(30);

    private sealed class AuthCode
    {
        public required string Value { get; init; }
        public required string ClientId { get; init; }
        public required string RedirectUri { get; init; }
        public required string CodeChallenge { get; init; }
        public required string UserId { get; init; }
        public required string Scope { get; init; }
        public required DateTimeOffset ExpiresAt { get; init; }
        public bool Used { get; set; }
        /// <summary>The grant (token family) minted from this code. Null until the code was exchanged successfully.</summary>
        public string? FamilyId { get; set; }
    }

    /// <summary>Every token minted from one grant: the unit that is revoked when a code or refresh token is replayed.</summary>
    private sealed class Family
    {
        public required string Id { get; init; }
        public required string ClientId { get; init; }
        public required string Subject { get; init; }
        public required string Scope { get; init; }
        public bool Revoked { get; set; }
    }

    private sealed class AccessRecord
    {
        public required string Value { get; init; }
        public required string FamilyId { get; init; }
        public required DateTimeOffset ExpiresAt { get; init; }
        public bool Revoked { get; set; }
    }

    private sealed class RefreshRecord
    {
        public required string Value { get; init; }
        public required string FamilyId { get; init; }
        public required DateTimeOffset ExpiresAt { get; init; }
        public bool Used { get; set; }
        public bool Revoked { get; set; }
    }

    private readonly TimeProvider _time;
    private readonly Dictionary<string, ClientRegistration> _clients = new();
    private readonly Dictionary<string, AuthCode> _codes = new();
    private readonly Dictionary<string, Family> _families = new();
    private readonly Dictionary<string, AccessRecord> _accessTokens = new();
    private readonly Dictionary<string, RefreshRecord> _refreshTokens = new();

    /// <summary>Which API (audience) each scope belongs to. A scope says what, the audience says which API may accept the token.</summary>
    private static readonly Dictionary<string, string> ScopeAudience = new()
    {
        ["reports.read"] = "reports-api",
        ["reports.write"] = "reports-api",
        ["billing.read"] = "billing-api",
    };

    public AuthorizationServer(TimeProvider time)
    {
        _time = time;
        Register("spa", null, ["http://localhost:6181/cb"], ["authorization_code", "refresh_token"], ["reports.read"]);
        Register("web", "web-secret", ["http://localhost:6182/cb"], ["authorization_code", "refresh_token"], ["reports.read", "reports.write", "billing.read"]);
        Register("worker", "worker-secret", [], ["client_credentials"], ["reports.read", "billing.read"]);
        // A registration with a wildcard: under exact matching it only matches the literal string, never a page under the prefix.
        Register("legacy", null, ["http://localhost:6181/*"], ["authorization_code"], ["reports.read"]);
    }

    private void Register(string id, string? secret, string[] redirectUris, string[] grants, string[] scopes) =>
        _clients[id] = new ClientRegistration(id, secret, redirectUris.ToHashSet(), grants.ToHashSet(), scopes.ToHashSet());

    private static string NewToken() => Convert.ToBase64String(RandomNumberGenerator.GetBytes(32)).TrimEnd('=').Replace('+', '-').Replace('/', '_');

    private static string[] SplitScope(string? scope) => (scope ?? "").Split(' ', StringSplitOptions.RemoveEmptyEntries);

    private static string[] AudiencesOf(string scope) =>
        [.. SplitScope(scope).Select(s => ScopeAudience[s]).Distinct()];

    /// <summary>Client authentication at the token endpoint. Returns null when the client is who it says; otherwise the error to send.</summary>
    private TokenResponse? AuthenticateClient(string? id, string? secret, out ClientRegistration client)
    {
        client = null!;
        if (id is null || !_clients.TryGetValue(id, out var found)) return TokenResponse.Failure("invalid_client", 401);
        if (found.IsConfidential)
        {
            var given = Encoding.UTF8.GetBytes(secret ?? "");
            if (!CryptographicOperations.FixedTimeEquals(Encoding.UTF8.GetBytes(found.Secret!), given))
                return TokenResponse.Failure("invalid_client", 401);
        }
        client = found;
        return null;
    }

    private Family NewFamily(ClientRegistration client, string subject, string scope)
    {
        var family = new Family { Id = NewToken(), ClientId = client.Id, Subject = subject, Scope = scope };
        _families[family.Id] = family;
        return family;
    }

    private void RevokeFamily(string familyId) => _families[familyId].Revoked = true;

    private TokenResponse IssueTokens(Family family, bool withRefreshToken)
    {
        var now = _time.GetUtcNow();
        var access = new AccessRecord { Value = NewToken(), FamilyId = family.Id, ExpiresAt = now + AccessTokenLifetime };
        _accessTokens[access.Value] = access;

        string? refresh = null;
        if (withRefreshToken)
        {
            var record = new RefreshRecord { Value = NewToken(), FamilyId = family.Id, ExpiresAt = now + RefreshTokenLifetime };
            _refreshTokens[record.Value] = record;
            refresh = record.Value;
        }

        return new TokenResponse(200, AccessToken: access.Value, RefreshToken: refresh, Scope: family.Scope, ExpiresIn: (int)AccessTokenLifetime.TotalSeconds);
    }

    /// <summary>RFC 7662. Active means: known, not expired, not revoked, and its grant was not revoked.</summary>
    public Introspection Introspect(string? token)
    {
        if (token is null) return Introspection.Inactive;
        var now = _time.GetUtcNow();

        if (_accessTokens.TryGetValue(token, out var access))
        {
            var family = _families[access.FamilyId];
            if (access.Revoked || family.Revoked || now >= access.ExpiresAt) return Introspection.Inactive;
            return new Introspection(true, family.ClientId, family.Subject, family.Scope, AudiencesOf(family.Scope), access.ExpiresAt.ToUnixTimeSeconds());
        }

        if (_refreshTokens.TryGetValue(token, out var refresh))
        {
            var family = _families[refresh.FamilyId];
            if (refresh.Used || refresh.Revoked || family.Revoked || now >= refresh.ExpiresAt) return Introspection.Inactive;
            return new Introspection(true, family.ClientId, family.Subject, family.Scope, [], refresh.ExpiresAt.ToUnixTimeSeconds());
        }

        return Introspection.Inactive;
    }

    private Redirect Fail(AuthorizeRequest request, string error)
    {
        var parameters = new Dictionary<string, string> { ["error"] = error, ["iss"] = Issuer };
        if (request.State is not null) parameters["state"] = request.State;
        return new Redirect(request.RedirectUri!, parameters);
    }
}
